}
fn _csv_row(t: _CsvTable, n: i64) std.ArrayList([]const u8) {
    var _r: std.ArrayList([]const u8) = .empty;
    const _i: usize = @intCast(@max(0, n));
    if (_i < t.rows.len) for (t.rows[_i]) |f| _r.append(std.heap.page_allocator, f) catch {};
