        },
        .ip6 => {},
    }
    return _result;
}
// ─── Thompson NFA regex engine ───────────────────────────────────────────────
const _RNodeKind = enum(u8) { match, lit, dot, cls, split, save, bol, eol_a, wb };
const _RNode = struct {
